class Solution {
public:
    long long maximizeSum(vector<int>& nums, int k) {
        long long total = 0;
        vector<long long> gains;
        gains.reserve(nums.size());
        for (int x : nums) {
            total += x;
            string s = to_string(x);
            sort(s.begin(), s.end(), greater<char>());
            long long maxVal = stoll(s);
            long long gain = maxVal - x;
            if (gain > 0) gains.push_back(gain);
        }
        sort(gains.begin(), gains.end(), greater<long long>());
        int limit = min(k, (int)gains.size());
        for (int i = 0; i < limit; ++i) total += gains[i];
        return total;
    }
};
